function extraForm(kind,key,client=null,bolo=null){const row=key?pick(tableBy[kind]||'at_contactos',key)||{}:{};let fields='';
 if(kind==='contactos'){fields=`<input type="hidden" name="cliente_id" value="${Number(client||row.cliente_id)}">${input('Nombre','nombre',row.nombre,'text',true,'required')}${input('Cargo / relación','cargo',row.cargo)}${input('Correo','email',row.email,'email')}${input('Teléfono','telefono',row.telefono,'tel')}${texta('Notas','notas',row.notas)}`;}
 if(kind==='seguimientos'){fields=`<label>Cliente<select name="cliente_id">${opts(state.data.at_clientes||[],client||row.cliente_id)}</select></label><label>Bolo<select name="bolo_id">${optionsBolo(bolo||row.bolo_id)}</select></label>${select('Tipo','tipo',[['llamada','Llamada'],['email','Email'],['reunion','Reunión'],['whatsapp','WhatsApp'],['nota','Nota']],row.tipo||'nota')}${input('Próxima gestión','proxima_fecha',row.proxima_fecha,'date')}${texta('Gestión realizada / acuerdos','descripcion',row.descripcion)}`;}
 if(kind==='materiales'){fields=`${input('Título','titulo',row.titulo,'text',true,'required')}<label>Bolo<select name="bolo_id">${optionsBolo(bolo||row.bolo_id)}</select></label>${select('Categoría','categoria',[['partitura','Partitura'],['audio','Audio'],['video','Vídeo'],['documento','Documento'],['presupuesto','Presupuesto'],['contrato','Contrato'],['otro','Otro']],row.categoria||'documento')}${input('Enlace HTTPS (si no subes archivo)','enlace',row.enlace,'url',true)}<label class="full">Archivo privado · hasta 20 MB<input name="archivo" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.mp3,.m4a,.ogg,.wav,.mp4,.docx,.xlsx,.txt"></label>${texta('Notas','notas',row.notas)}<p class="small full">Los archivos solo son accesibles a integrantes autorizados. Los enlaces externos conservan sus propios permisos.</p>`;}
 open(key?'Editar registro':'Añadir registro',`<form id="extraForm" onsubmit="event.preventDefault();app.saveExtra('${kind}',${key||'null'})"><div class="field-grid">${fields}</div><p id="extraError" role="status"></p><button id="extraSave" class="btn primary">Guardar</button></form>`);
}
async function saveExtra(kind,key){if(!state.ready)return;const f=id('extraForm'),btn=id('extraSave');btn.disabled=true;const fd=new FormData(f),row=Object.fromEntries(fd);delete row.archivo;let uploaded=null,persisted=false;const errorEl=id('extraError');try{
 for(const field of ['cliente_id','bolo_id'])if(field in row)row[field]=row[field]?Number(row[field]):null;
 if('proxima_fecha'in row&&!row.proxima_fecha)row.proxima_fecha=null;
 if(kind==='seguimientos'&&!row.descripcion.trim())throw Error('Describe la gestión realizada.');
 if(kind==='materiales'){
  if(row.enlace&&!/^https:\/\//i.test(row.enlace))throw Error('El enlace debe empezar por https://');
  const file=fd.get('archivo');if(file?.size){if(file.size>20*1024*1024)throw Error('El archivo supera los 20 MB.');const suffix=(file.name.split('.').pop()||'').toLowerCase();if(!['pdf','png','jpg','jpeg','webp','mp3','m4a','ogg','wav','mp4','docx','xlsx','txt'].includes(suffix))throw Error('Formato de archivo no admitido.');const path=state.user.id+'/'+crypto.randomUUID()+'.'+suffix;const types={pdf:'application/pdf',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp',mp3:'audio/mpeg',m4a:'audio/mp4',ogg:'audio/ogg',wav:'audio/wav',mp4:'video/mp4',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',txt:'text/plain'};const {error}=await sb.storage.from('attempo-materiales').upload(path,file,{contentType:types[suffix],upsert:false});if(error)throw Error('No se pudo subir el archivo. Comprueba la conexión.');uploaded=path;row.ruta=path;row.nombre_archivo=file.name;row.tamano=file.size;}
  if(!key&&!row.ruta&&!row.enlace)throw Error('Sube un archivo o añade un enlace.');
 }
 const table=kind==='contactos'?'at_contactos':tableBy[kind];const {error}=key?await sb.from(table).update(row).eq('id',key):await sb.from(table).insert(row);if(error)throw error;persisted=true;
 if(uploaded&&key){const old=pick('at_materiales',key);if(old?.ruta)await sb.storage.from('attempo-materiales').remove([old.ruta]);}
 close();await load();render();if(kind==='contactos'&&row.cliente_id)detail('clientes',row.cliente_id);
 }catch(e){if(uploaded&&!persisted)await sb.storage.from('attempo-materiales').remove([uploaded]);if(errorEl?.isConnected)errorEl.textContent=e.message||'No se pudo guardar.';else alert(persisted?'El registro se guardó, pero no se pudo actualizar la vista. Pulsa Actualizar.':e.message||'No se pudo guardar.');}finally{btn.disabled=false;}}
async function openMaterial(key){if(!state.ready)return;const x=pick('at_materiales',key);if(!x)return;let url=x.enlace;if(x.ruta){const {data,error}=await sb.storage.from('attempo-materiales').createSignedUrl(x.ruta,120);if(error){alert('No se pudo abrir el archivo.');return;}url=data.signedUrl;}if(!/^https:\/\//i.test(url)){alert('Enlace no válido.');return;}open('Abrir material',`<p>${safe(x.titulo)}</p><a class="btn primary" href="${safe(url)}" target="_blank" rel="noopener noreferrer">Abrir / descargar archivo</a><p class="small">El enlace privado de descarga caduca en dos minutos.</p>`);}
async function deleteExtra(kind,key){if(!state.ready||!confirm('¿Eliminar este registro?'))return;const table=kind==='contactos'?'at_contactos':tableBy[kind],x=pick(table,key);if(!x)return;if(kind==='materiales'&&x.ruta){const {error}=await sb.storage.from('attempo-materiales').remove([x.ruta]);if(error){alert('No se pudo borrar el archivo.');return;}}const {error}=await sb.from(table).delete().eq('id',key);if(error){alert('No se pudo eliminar el registro.');return;}close();await load();render();}
function extraCard(kind,x){if(kind==='materiales')return `<article class="card"><h3>${safe(x.titulo)}</h3><p>${safe(x.categoria)} · ${safe(boloName(x.bolo_id))}</p><p>${safe(x.nombre_archivo)} ${x.tamano?'· '+(x.tamano/1024/1024).toFixed(1)+' MB':''}</p><p>${safe(x.notas)}</p>${actions([['Abrir',`app.openMaterial(${x.id})`,true],['Editar',`app.extraForm('materiales',${x.id})`],['Eliminar',`app.deleteExtra('materiales',${x.id})`]])}</article>`;
 return `<article class="card"><h3>${safe(x.tipo)} · ${short(x.creado_en)}</h3><p>${safe(cliName(x.cliente_id))} · ${safe(boloName(x.bolo_id))}</p><div class="notes">${safe(x.descripcion)}</div><p>Próxima gestión: ${short(x.proxima_fecha)}</p>${actions([['Editar',`app.extraForm('seguimientos',${x.id})`,true],['Eliminar',`app.deleteExtra('seguimientos',${x.id})`]])}</article>`;}
function extraView(kind){id('content').innerHTML=filterBar(false)+`<div class="cards">${listaFiltrada(kind).map(x=>extraCard(kind,x)).join('')||'<div class="empty">Todavía no hay registros.</div>'}</div>`;}
function clientExtras(key){const contacts=(state.data.at_contactos||[]).filter(x=>x.cliente_id===key),history=(state.data.at_seguimientos||[]).filter(x=>x.cliente_id===key).sort((a,b)=>b.creado_en.localeCompare(a.creado_en));return `<h4>Otros contactos</h4>${contacts.map(x=>`<article class="card"><strong>${safe(x.nombre)}</strong><p>${safe(x.cargo)} · ${safe(x.email)} · ${safe(x.telefono)}</p><p>${safe(x.notas)}</p>${actions([['Editar',`app.extraForm('contactos',${x.id},${key})`],['Eliminar',`app.deleteExtra('contactos',${x.id})`]])}</article>`).join('')||'<p>Sin contactos adicionales.</p>'}${actions([['Añadir contacto',`app.extraForm('contactos',null,${key})`,true],['Registrar gestión',`app.extraForm('seguimientos',null,${key})`]])}<h4>Historial comercial</h4>${history.map(x=>extraCard('seguimientos',x)).join('')||'<p>Sin gestiones registradas.</p>'}`;}
function reportRows(){return(state.data.at_bolos||[]).map(b=>{const budgets=(state.data.at_presupuestos||[]).filter(x=>x.bolo_id===b.id),accepted=budgets.filter(x=>x.estado==='aceptado'),latest=accepted.sort((a,b)=>b.id-a.id)[0],income=latest?Number(latest.importe):Number(b.importe||0),cost=(state.data.at_gastos||[]).filter(x=>x.bolo_id===b.id).reduce((s,x)=>s+Number(x.importe),0),polls=(state.data.at_encuestas||[]).filter(x=>x.bolo_id===b.id).sort((a,b)=>b.id-a.id),p=polls[0],answers=(state.data.at_respuestas||[]).filter(x=>x.encuesta_id===p?.id),active=new Set((state.data.at_miembros||[]).filter(m=>m.activo).map(m=>m.id)),valid=answers.filter(x=>active.has(x.usuario_id));return {id:b.id,titulo:b.titulo,fecha:b.fecha,estado:status[b.estado]||b.estado,ingreso:income,origen:latest?'Último presupuesto aceptado':'Importe previsto del bolo',gastos:cost,margen:income-cost,si:valid.filter(x=>x.respuesta==='si').length,duda:valid.filter(x=>x.respuesta==='duda').length,no:valid.filter(x=>x.respuesta==='no').length,pendientes:p?active.size-valid.length:active.size,encuesta:p?'Sí':'Sin encuesta',...voiceViability(b.id)};});}
function reports(){const rows=reportRows();id('content').innerHTML=`<div class="insight"><strong>Previsión y disponibilidad</strong><p>Se usa el último presupuesto aceptado de cada bolo o, si no existe, su importe previsto. El margen descuenta todos los gastos registrados. No representa cobros ni beneficio contable.</p><p>La disponibilidad corresponde a la última encuesta del bolo. La decisión artística requiere revisar las voces necesarias.</p></div>${actions([['Exportar informe CSV · Excel','app.exportReport()',true],['Exportar clientes','app.exportData("at_clientes")'],['Exportar gastos','app.exportData("at_gastos")'],['Exportar tareas','app.exportData("at_tareas")']])}<div class="cards">${rows.map(r=>`<article class="card"><h3>${safe(r.titulo)}</h3><p>${short(r.fecha)} · ${safe(r.estado)}</p><p>Previsto: ${money(r.ingreso)} · Gastos: ${money(r.gastos)}</p><p><strong>Margen previsto: ${money(r.margen)}</strong></p><p class="small">${safe(r.origen)}</p><p>Sí: ${r.si} · Dudas: ${r.duda} · No: ${r.no} · Pendientes: ${r.pendientes} · ${r.encuesta}</p><p><strong>${safe(r.viabilidad)}</strong></p><p class="small">${safe(r.voces)} · Sí sin cuerda indicada: ${r.sin_cuerda}</p><button class="btn" onclick="app.detail('bolos',${r.id})">Ver expediente</button></article>`).join('')||'<div class="empty">Añade bolos para ver el informe.</div>'}</div>`;}
function csvDownload(name,rows){if(!rows.length){alert('No hay datos para exportar.');return;}const headers=Object.keys(rows[0]);const cell=v=>{let s=v==null?'':typeof v==='object'?JSON.stringify(v):String(v);if(/^[\s]*[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const csv='\ufeff'+[headers,...rows.map(r=>headers.map(k=>r[k]))].map(r=>r.map(cell).join(';')).join('\r\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='ATTEMPO-'+name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportReport(){if(state.ready)csvDownload('informe',reportRows());}
function exportData(table){if(state.ready&&['at_clientes','at_gastos','at_tareas'].includes(table))csvDownload(table.slice(3),state.data[table]||[]);}
function openPlaylist(key){const x=pick('at_repertorio',key);if(x?.playlist&&/^https:\/\//i.test(x.playlist))window.open(x.playlist,'_blank','noopener,noreferrer');}
function taskPointer(event,key){if(event.button!==0)return;event.preventDefault();const button=event.currentTarget;button.setPointerCapture(event.pointerId);let target=key;const move=e=>{const card=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-task]');if(card){target=Number(card.dataset.task);document.querySelectorAll('[data-task]').forEach(c=>c.style.outline='');card.style.outline='2px solid #485565';}};const done=()=>{button.removeEventListener('pointermove',move);button.removeEventListener('pointerup',up);button.removeEventListener('pointercancel',cancel);document.querySelectorAll('[data-task]').forEach(c=>c.style.outline='');};const up=()=>{done();if(target!==key)dropTask(key,target);};const cancel=()=>done();button.addEventListener('pointermove',move);button.addEventListener('pointerup',up);button.addEventListener('pointercancel',cancel);}
function wireDashboard(){id('content').querySelectorAll('.metric').forEach((el,i)=>{el.tabIndex=0;el.setAttribute('role','button');el.onclick=()=>dashboardTarget(i);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();dashboardTarget(i);}};});}
function dashboardTarget(i){if(i===3){nav('presupuestos');state.filter='__enviados';}else{nav('bolos');state.filter=['__activos','__contratados','cerrado'][i];}render();}


const voces=[['s1','Soprano 1'],['s2','Soprano 2'],['altos','Altos'],['tenores','Tenores'],['bajos','Bajos']];
function profileVoice(){const me=(state.data.at_miembros||[]).find(m=>m.id===state.user.id);return `<article class="card"><h3>Mi cuerda</h3><p>Se utiliza para revisar la viabilidad musical de las actuaciones.</p><div class="field-grid">${select('Cuerda','mi_cuerda',[['','Sin indicar'],...voces,['otra','Otra / acompañamiento']],me?.cuerda||'')}</div><button class="btn" onclick="app.saveVoice()">Guardar mi cuerda</button><p id="voiceStatus" role="status"></p></article>`;}
function voiceRequirements(key){const b=pick('at_bolos',key);if(!b)return;open('Mínimos de voces para este bolo',`<p>Define los mínimos que necesita este programa. Un cero deja esa cuerda sin mínimo. No se aplican cifras de otro coro.</p><form id="voicesForm" onsubmit="event.preventDefault();app.saveRequirements(${key})"><div class="field-grid">${voces.map(([k,label])=>input(label,'min_'+k,b['min_'+k]||0,'number',false,'required min="0" max="500" step="1"')).join('')}</div><p id="voicesError" role="status"></p><button class="btn primary">Guardar mínimos</button></form>`);}
async function saveRequirements(key){if(!state.ready)return;const raw=Object.fromEntries(new FormData(id('voicesForm'))),data={};for(const [k,v]of Object.entries(raw)){data[k]=Number(v);if(!Number.isInteger(data[k])||data[k]<0||data[k]>500){id('voicesError').textContent='Introduce números enteros entre 0 y 500.';return;}}const {error}=await sb.from('at_bolos').update(data).eq('id',key);if(error){id('voicesError').textContent='No se pudo guardar.';return;}close();await load();render();}
function voiceViability(bolo){const b=pick('at_bolos',bolo),p=(state.data.at_encuestas||[]).filter(p=>p.bolo_id===bolo).sort((a,b)=>b.id-a.id)[0],answers=(state.data.at_respuestas||[]).filter(a=>a.encuesta_id===p?.id&&a.respuesta==='si'),yes=new Set(answers.map(a=>a.usuario_id)),members=(state.data.at_miembros||[]).filter(m=>m.activo&&yes.has(m.id));let has=false,missing=false;const summary=voces.map(([k,label])=>{const count=members.filter(m=>m.cuerda===k).length,min=Number(b?.['min_'+k])||0;if(min>0)has=true;if(count<min)missing=true;return label+': '+count+(min?' / mínimo '+min:'');}).join(' · ');return {viabilidad:!p?'Sin encuesta':!has?'Sin mínimos definidos':missing?'Faltan voces':'Mínimos cubiertos',voces:summary,sin_cuerda:members.filter(m=>!m.cuerda).length};}

